373	        right05.crossVectors(up05, back).normalize();
374	        basis.makeBasis(right05, up05, back);
375	      } else {
376	        back.copy(f.tan).negate();
377	        const right = new THREE.Vector3().crossVectors(f.up, back).normalize();
